//! Probe regressions on synthetic PDFs (generated by `fixtures/make_pdfs.py`). Each expectation is the worker's own
//! routing decision for that file (council review 2026-11-03, `authorizeRasterPageOcr` over pdftotext/pdfimages/
//! pdfinfo evidence), so a probe that disagrees with what the worker bills fails here.

use std::time::{Duration, Instant};

use docslurp_estimate::card::{Card, PageMix};
use docslurp_estimate::probe::{probe, ProbeInput, ProbeResult};

fn probe_fixture(name: &str) -> ProbeResult {
    let path = format!("{}/tests/fixtures/{name}", env!("CARGO_MANIFEST_DIR"));
    let bytes = std::fs::read(&path).unwrap_or_else(|error| panic!("{path}: {error}"));
    probe(Card::bundled(), &ProbeInput::whole(name, None, &bytes))
}

fn scanned_share(result: &ProbeResult) -> f64 {
    result.mix.map(|PageMix { scanned, .. }| scanned).unwrap_or_else(|| panic!("no mix: {result:?}"))
}

#[test]
fn full_page_scans_are_scanned() {
    for name in ["scan_plain.pdf", "scan_inline.pdf"] {
        assert_eq!(scanned_share(&probe_fixture(name)), 1.0, "{name}");
    }
}

#[test]
fn coverage_is_measured_over_the_crop_box() {
    // MediaBox 3x the CropBox, scan filling the CropBox: the worker sees full coverage.
    assert_eq!(scanned_share(&probe_fixture("scan_big_mediabox.pdf")), 1.0);
}

#[test]
fn a_title_drawn_glyph_by_glyph_does_not_hide_a_scan() {
    assert_eq!(scanned_share(&probe_fixture("scan_glyph_title.pdf")), 1.0);
}

#[test]
fn text_pages_with_images_or_ocr_layers_bill_fast() {
    for name in ["scan_ocr_invisible_wrapped.pdf", "text_wrapped_with_photo.pdf"] {
        assert_eq!(scanned_share(&probe_fixture(name)), 0.0, "{name}");
    }
}

#[test]
fn a_vector_page_in_a_text_document_is_blank_not_scanned() {
    let result = probe_fixture("vector_page_in_text_doc.pdf");
    assert_eq!(result.pages, Some(2.0));
    assert_eq!(scanned_share(&result), 0.0);
}

#[test]
fn a_form_drawn_thousands_of_times_stays_within_budget() {
    let started = Instant::now();
    let result = probe_fixture("form_amplification.pdf");
    assert!(started.elapsed() < Duration::from_secs(5), "took {:?}", started.elapsed());
    assert_eq!(result.pages, Some(1.0));
}

#[test]
fn a_page_tree_cycle_returns() {
    let _ = probe_fixture("page_tree_cycle.pdf");
}

#[test]
fn pages_without_text_but_with_any_image_bill_rich() {
    // 20 pages, no text layer, a small logo on each: the worker bills every page Rich (page-base-fee.ts).
    let result = probe_fixture("no_text_small_images.pdf");
    assert_eq!(result.pages, Some(20.0));
    assert_eq!(scanned_share(&result), 1.0);
}

/// Many object streams that each decode to 15 MiB of spaces: under lopdf's per-stream limit, far over the probe's
/// 64 MiB document budget. `type_name` and `double_flate` cover the council's bypasses of a raw-text check
/// (`#`-escaped names, nested filters).
fn object_stream_bomb(type_name: &str, double_flate: bool) -> Vec<u8> {
    let chunk = vec![b' '; 15 * 1024 * 1024];
    let mut compressed = miniz_oxide::deflate::compress_to_vec_zlib(&chunk, 9);
    if double_flate {
        compressed = miniz_oxide::deflate::compress_to_vec_zlib(&compressed, 9);
    }
    let filter = if double_flate { "[/FlateDecode /FlateDecode]" } else { "/FlateDecode" };
    let mut pdf = b"%PDF-1.7\n".to_vec();
    for number in 1..=40 {
        pdf.extend_from_slice(
            format!("{number} 0 obj\n<< /Type {type_name} /N 1 /First 4 /Filter {filter} /Length {} >>\nstream\n", compressed.len())
                .as_bytes(),
        );
        pdf.extend_from_slice(&compressed);
        pdf.extend_from_slice(b"\nendstream\nendobj\n");
    }
    pdf.extend_from_slice(b"trailer\n<< /Root 1 0 R >>\n%%EOF\n");
    pdf
}

#[test]
fn object_stream_bombs_are_refused_within_the_document_budget() {
    for (type_name, double_flate) in [("/ObjStm", false), ("/ObjSt#6D", false), ("/ObjStm", true), ("/O#62jStm", true)] {
        let pdf = object_stream_bomb(type_name, double_flate);
        let started = Instant::now();
        let result = probe(Card::bundled(), &ProbeInput::whole("bomb.pdf", None, &pdf));
        assert!(started.elapsed() < Duration::from_secs(10), "{type_name} {double_flate}: took {:?}", started.elapsed());
        assert!(result.mix.is_none(), "{type_name} {double_flate}");
        assert!(result.notes.iter().any(|note| note.contains("object streams")), "{type_name} {double_flate}: {:?}", result.notes);
    }
}

#[test]
fn encrypted_files_are_not_loaded() {
    let pdf = b"%PDF-1.7\n1 0 obj << /Type /Page >> endobj\ntrailer << /Root 1 0 R /Encr#79pt 2 0 R >>\n%%EOF";
    let result = probe(Card::bundled(), &ProbeInput::whole("locked.pdf", None, pdf));
    assert_eq!(result.pages, Some(1.0));
    assert!(result.notes.iter().any(|note| note.contains("encrypted")));
}
